 * Transcript parsing utilities for Qwen Code CLI JSONL transcripts.
 *
 * Each line of a transcript is a `ChatRecord`. Messages use the Gemini
 * content format (`{ role, parts }`), where each part is a text part, a
 * functionCall, or a functionResponse.
 */

import { readFileSync } from 'node:fs';
import type { ChatRecord, GeminiPart } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;

/**
 * Read and parse a Qwen Code JSONL transcript file.
 */
export function readTranscript(path: string): ChatRecord[] {
  const content = readFileSync(path, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as ChatRecord);
}

/**
 * Parse an ISO 8601 timestamp string to nanoseconds since the Unix epoch
 * (epoch milliseconds * 1,000,000). Returns null for null, undefined, or
 * empty string input.
 */
export function parseTimestampToNs(timestamp: string | null | undefined): number | null {
  if (!timestamp) {
    return null;
  }
  try {
    const ms = new Date(timestamp).getTime();
    if (isNaN(ms)) {
      return null;
    }
    return ms * NANOSECONDS_PER_MS;
  } catch {
    return null;
  }
}

/**
 * Type guard: true when a GeminiPart carries text.
 */
export function isTextPart(part: GeminiPart): boolean {
  return part != null && typeof part === 'object' && 'text' in part;
}

/**
 * Type guard: true when a GeminiPart carries a functionCall.
 */
export function isFunctionCallPart(part: GeminiPart): boolean {
  return part != null && typeof part === 'object' && 'functionCall' in part;
}

/**
 * Extract text content from a ChatRecord's message.
 *
 * Joins all text parts with a newline. Excludes parts where `thought=true` by
 * default; includes them when `includeThoughts=true`. A plain string message
 * is returned as-is. functionCall and functionResponse parts contribute no
 * text and are skipped.
 */
export function getMessageText(record: ChatRecord, includeThoughts = false): string {
  const message = record.message;
  if (message == null) {
    return '';
  }
  if (typeof message === 'string') {
    return message;
  }
  const parts = message.parts ?? [];
  return parts
    .filter((part): part is { text: string; thought?: boolean } => isTextPart(part))
    .filter((part) => includeThoughts || !part.thought)
    .map((part) => part.text)
    .join('\n');
}

/**
 * Extract all functionCall parts from a ChatRecord's message. Returns an empty
 * array for records with no message or no functionCall parts.
 */
export function getFunctionCalls(
  record: ChatRecord,
): Array<{ id: string; name: string; args?: Record<string, any> }> {
  const message = record.message;
  if (message == null || typeof message === 'string') {
    return [];
  }
  const parts = message.parts ?? [];
  return parts
    .filter(isFunctionCallPart)
    .map((part) => (part as { functionCall: { id: string; name: string; args?: Record<string, any> } }).functionCall)
    .map((call) => ({ id: call.id, name: call.name, args: call.args }));
}

/**
 * Build a map from `toolCallResult.callId` to the `tool_result` record.
 * Non-tool_result records are excluded.
 */
export function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {
  const map = new Map<string, ChatRecord>();
  for (const record of records) {
    if (record.type !== 'tool_result') {
      continue;
    }
    const callId = record.toolCallResult?.callId;
    if (callId != null) {
      map.set(callId, record);
    }
  }
  return map;
}

/**
 * Normalize a resultDisplay value to a string. Passes strings through
 * unchanged, JSON.stringifies objects, and returns an empty string for
 * null or undefined.
 */
export function formatResultDisplay(display: any): string {
  if (display == null) {
    return '';
  }
  if (typeof display === 'string') {
    return display;
  }
  return JSON.stringify(display);
}

/**
 * Extract tool output from a tool_result record.
 *
 * Prefers `toolCallResult.resultDisplay` (normalized via formatResultDisplay).
 * When resultDisplay is absent, falls back to JSON.stringify of the
 * functionResponse.response found in the message parts. Returns an empty
 * string when neither is available.
 */
export function getToolOutput(record: ChatRecord): string {
  const resultDisplay = record.toolCallResult?.resultDisplay;
  if (resultDisplay != null) {
    return formatResultDisplay(resultDisplay);
  }

  const message = record.message;
  if (message != null && typeof message !== 'string') {
    const parts = message.parts ?? [];
    for (const part of parts) {
      if (part != null && typeof part === 'object' && 'functionResponse' in part) {
        return JSON.stringify(
          (part as { functionResponse: { response: any } }).functionResponse.response,
        );
      }
    }
  }
  return '';
}

/**
 * Return the records belonging to the last turn: a slice starting at the last
 * record whose type is 'user' and continuing to the end of the array.
 */
export function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {
  let lastUser = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    if (records[i].type === 'user') {
      lastUser = i;
      break;
    }
  }
  if (lastUser < 0) {
    return records;
  }
  return records.slice(lastUser);
}

/**
 * Extract token counts from a usageMetadata object. Maps promptTokenCount to
 * `input`, candidatesTokenCount to `output`, totalTokenCount to `total`.
 * Returns null when the argument is undefined or missing.
 */
export function getTokenUsage(
  usageMetadata: any,
): { input: number; output: number; total: number } | null {
  if (usageMetadata == null) {
    return null;
  }
  return {
    input: usageMetadata.promptTokenCount,
    output: usageMetadata.candidatesTokenCount,
    total: usageMetadata.totalTokenCount,
  };
}
