 * - Assistant records with functionCall parts →
 *   `{ role: 'assistant', content: null, tool_calls: [...] }`
 * - tool_result records → `{ role: 'tool', tool_call_id, content }`
 * - System records with a message → `{ role: 'system', content }`
 * - System records without a message → excluded
 */
export function reconstructMessages(records: ChatRecord[], targetIndex: number): ChatMessage[] {
  const messages: ChatMessage[] = [];
  for (let i = 0; i < targetIndex; i++) {
    const record = records[i];

    if (record.type === 'user') {
      messages.push({ role: 'user', content: getMessageText(record) });
    } else if (record.type === 'assistant') {
      const functionCalls = getFunctionCalls(record);
      if (functionCalls.length > 0) {
        messages.push({
          role: 'assistant',
          content: null,
          tool_calls: functionCalls.map((call) => ({
            id: call.id,
            type: 'function',
            function: {
              name: call.name,
              arguments: JSON.stringify(call.args ?? {}),
            },
          })),
        });
      } else {
        messages.push({ role: 'assistant', content: getMessageText(record) });
